"""Original spatial tasks, with explicit geometry and paper-review criteria."""
from common import L, task, number, choice, multi, manual, cells, figure, error


def grid(rows, cols, filled=()):
    return {"rows": rows, "cols": cols, "filled": list(filled)}


def tasks():
    out = []

    def add(skill, slug, de, en, prompt_de, prompt_en, parts, use, hints,
            solution, level=2, fig=None, seconds=105):
        out.append(task(skill, slug, "geometry", de, en, prompt_de, prompt_en,
                        parts, use=use, hints=hints, solution=solution,
                        level=level, fig=fig, seconds=seconds))

    s = "M-R01"
    add(s, "rectangle_properties", "Eigenschaften eines Rechtecks", "Properties of a rectangle", "Die Zeichnung zeigt ein Rechteck mit Seitenlängen 6 cm und 3 cm. Nutze die Eigenschaften, nicht das Messen am Bildschirm.", "The drawing shows a rectangle with side lengths 6 cm and 3 cm. Use its properties; do not measure the screen.",
        [multi("properties", "Welche Aussagen stimmen? Wähle alle.", "Which statements are true? Select all.", [("right", "Es hat vier rechte Winkel.", "It has four right angles."), ("opposite", "Gegenüberliegende Seiten sind gleich lang.", "Opposite sides have equal lengths."), ("all", "Alle vier Seiten sind gleich lang.", "All four sides have equal lengths."), ("three", "Es hat drei Ecken.", "It has three corners.")], ["right", "opposite"], s), number("corners", "Wie viele Ecken hat es?", "How many corners does it have?", 4, s)],
        "practice", [("Ein rechter Winkel ist eine rechtwinklige Ecke wie an einem Blatt Papier.", "A right angle is a square corner like a corner of a sheet of paper.")], ("Vier rechte Winkel und gleich lange gegenüberliegende Seiten sind richtig. 6 cm und 3 cm sind verschieden, daher sind nicht alle Seiten gleich lang.", "Four right angles and equal opposite sides are correct. 6 cm and 3 cm differ, so not all sides are equal."), level=1,
        fig=figure("polygon", {"points": [[0, 0], [6, 0], [6, 3], [0, 3]]}, "Viereck mit vier rechten Winkeln, Seitenlängen 6 cm und 3 cm.", "Quadrilateral with four right angles and side lengths 6 cm and 3 cm."))
    add(s, "tilted_square", "Ein gedrehtes Quadrat", "A tilted square", "Das gezeichnete Viereck hat vier gleich lange Seiten und vier rechte Winkel. Es steht schräg auf der Seite. Hier gilt: Ein Quadrat ist auch ein besonderes Rechteck.", "The drawn quadrilateral has four equal sides and four right angles. It is tilted on the page. A square is also a special rectangle.",
        [multi("names", "Welche Namen passen?", "Which names apply?", [("square", "Quadrat", "Square"), ("rectangle", "Rechteck", "Rectangle"), ("triangle", "Dreieck", "Triangle")], ["square", "rectangle"], s), manual("rotation", "Ändert die Drehung die Seitenlängen oder Winkel? Erkläre kurz.", "Does turning it change its side lengths or angles? Explain briefly.", "1 Punkt: Nein; beim Drehen bleiben Längen und Winkel unverändert. Die Lage allein bestimmt den Figurennamen nicht.", "1 point: no; rotation preserves lengths and angles. Position alone does not determine the shape's name.", s)],
        "practice", [("Entscheidend sind Eigenschaften, nicht die Richtung der Seiten auf dem Blatt.", "The properties matter, not the direction of the sides on the page.")], ("Die Figur ist Quadrat und Rechteck. Eine Drehung verändert weder Seitenlängen noch Winkel.", "The figure is both a square and a rectangle. Turning it changes neither side lengths nor angles."),
        fig=figure("polygon", {"points": [[0, 2], [2, 0], [4, 2], [2, 4]]}, "Schräg dargestelltes Viereck mit vier gleich langen Seiten und vier rechten Winkeln.", "Tilted quadrilateral with four equal sides and four right angles."))
    add(s, "property_table_classification", "Figuren nach Angaben einordnen", "Classify shapes from properties", "Die Tabelle beschreibt drei Vierecke. Ein Rechteck hat vier rechte Winkel; ein Quadrat ist ein Rechteck mit vier gleich langen Seiten.", "The table describes three quadrilaterals. A rectangle has four right angles; a square is a rectangle with four equal sides.",
        [multi("rectangles", "Welche Figuren sind Rechtecke? Wähle alle.", "Which figures are rectangles? Select all.", [(x, x, x) for x in ["A", "B", "C"]], ["A", "B"], s), choice("square", "Welche Figur ist ein Quadrat?", "Which figure is a square?", [(x, x, x) for x in ["A", "B", "C"]], "A", s)],
        "check", [("Prüfe für Rechtecke zuerst die Anzahl rechter Winkel.", "For rectangles, check the number of right angles first.")], ("A und B sind Rechtecke. A ist zusätzlich ein Quadrat. C hat gleiche Seiten, aber keine rechten Winkel.", "A and B are rectangles. A is also a square. C has equal sides but no right angles."),
        fig=figure("table", {"headers": [L("Figur", "Shape"), L("Seiten in cm", "Sides in cm"), L("Rechte Winkel", "Right angles")], "rows": [["A", "4, 4, 4, 4", "4"], ["B", "6, 3, 6, 3", "4"], ["C", "5, 5, 5, 5", "0"]]}, "A: vier Seiten zu 4 cm, vier rechte Winkel. B: 6, 3, 6, 3 cm, vier rechte Winkel. C: vier Seiten zu 5 cm, kein rechter Winkel.", "A: four 4 cm sides, four right angles. B: 6, 3, 6, 3 cm, four right angles. C: four 5 cm sides, no right angle."), seconds=90)
    add(s, "paper_rectangle_construction", "Ein Rechteck auf Papier", "Construct a rectangle on paper", "Nimm Papier und ein Lineal. Zeichne ein Rechteck mit 5 cm und 3 cm Seitenlänge. Diese Aufgabe wird an deiner Papierzeichnung geprüft, nicht durch Messen am Bildschirm.", "Use paper and a ruler. Draw a rectangle with side lengths 5 cm and 3 cm. Review the paper drawing, not measurements on the screen.",
        [manual("drawing", "Beschreibe kurz deine Zeichnung und lege sie zur Prüfung vor.", "Briefly describe your drawing and present it for review.", "2 Punkte: 1 für ein geschlossenes Viereck mit vier erkennbar rechten Winkeln und passenden gegenüberliegenden Seiten; 1 für Seitenlängen 5 cm und 3 cm mit höchstens 1 mm Abweichung je Seite. Bei fehlender Papierprüfung unbewertet lassen.", "2 points: 1 for a closed quadrilateral with four recognisable right angles and matching opposite sides; 1 for 5 cm and 3 cm side lengths within 1 mm per side. Leave unreviewed if the paper drawing cannot be checked.", s, points=2,
                rubric=[L("1 Punkt: geschlossenes Rechteck mit vier rechten Winkeln.", "1 point: closed rectangle with four right angles."), L("1 Punkt: 5 cm × 3 cm, Toleranz je Seite 1 mm.", "1 point: 5 cm × 3 cm, tolerance 1 mm per side.")])],
        "rehearsal", [("Zeichne zuerst eine Seite. Die benachbarte Seite muss rechtwinklig dazu liegen.", "Draw one side first. The adjacent side must be perpendicular to it.")], ("Ein korrektes Rechteck hat abwechselnd 5 cm, 3 cm, 5 cm und 3 cm lange Seiten sowie vier rechte Winkel. Die Orientierung ist beliebig.", "A correct rectangle has alternating side lengths 5 cm, 3 cm, 5 cm and 3 cm, with four right angles. Any orientation is valid."), seconds=150)

    s = "M-R02"
    add(s, "tile_rectangle_factors", "Rechtecke aus zwölf Plättchen", "Rectangles from twelve tiles", "Lege aus genau 12 gleich großen Quadratplättchen ein lückenloses Rechteck. Plättchen dürfen nicht überlappen. Gedrehte Rechtecke zählen als dieselbe Form.", "Use exactly 12 equal square tiles to make a rectangle with no gaps or overlaps. Rotated rectangles count as the same shape.",
        [multi("dimensions", "Welche Seitenpaare verwenden genau alle Plättchen?", "Which side pairs use exactly all tiles?", [("1x12", "1 und 12", "1 and 12"), ("2x6", "2 und 6", "2 and 6"), ("3x4", "3 und 4", "3 and 4"), ("2x5", "2 und 5", "2 and 5"), ("3x3", "3 und 3", "3 and 3")], ["1x12", "2x6", "3x4"], s), number("count", "Wie viele verschiedene Rechteckformen gibt es?", "How many different rectangle shapes are possible?", 3, s)],
        "practice", [("Suche Zahlenpaare mit dem Produkt 12.", "Find number pairs whose product is 12.")], ("1 · 12, 2 · 6 und 3 · 4 ergeben drei verschiedene Formen. Die umgekehrten Seitenpaare sind nur gedreht.", "1 × 12, 2 × 6 and 3 × 4 give three shapes. Reversed side pairs only rotate them."), level=1)
    missing = ["1,1", "1,2"]
