        [cells("reflection", "Wähle die drei Spiegelzellen rechts.", "Select the three reflected cells on the right.", ["0,4", "1,4", "1,3"], s, figure("mirror", mirror_data, "Vier Reihen, sechs Spalten; Spiegelachse nach Spalte drei. Gegeben sind Reihe 1 Spalte 2 sowie Reihe 2 Spalten 2 und 3.", "Four rows, six columns; mirror line after column three. Given cells: row 1 column 2, and row 2 columns 2 and 3."))],
