        [cells("extra", "Wähle nur das zusätzliche Quadrat.", "Select only the added square.", ["3,1"], s, figure("cubeNet", {"rows": 4, "cols": 3, "cells": five_cells, "labels": {}}, "Vier Reihen, drei Spalten: fest sind oben Mitte, in Reihe zwei alle drei Felder und in Reihe drei Mitte.", "Four rows, three columns: fixed cells are top middle, all three in row two, and middle in row three.")), manual("why", "Was wird aus der ergänzten Fläche beim Falten?", "What does the added face become when folded?", "1 Punkt: Sie schließt den Würfel gegenüber der mittleren Kreuzfläche; die sechs Flächen überdecken sich nicht.", "1 point: it closes the cube opposite the centre of the cross; the six faces do not overlap.", s)],
