    net_shapes = [{"id": "A", "cells": cross_cells}, {"id": "B", "cells": [f"{r},{c}" for r in range(2) for c in range(3)]}, {"id": "C", "cells": [f"0,{c}" for c in range(6)]}, {"id": "D", "cells": offset_cells}]
    add(s, "valid_net_selection", "Welche Netze schließen einen Würfel?", "Which nets form a cube?", "Jede Figur besteht aus sechs gleich großen Quadraten. Gefaltet wird nur an gemeinsamen Kanten, ohne Schneiden oder Überlappen.", "Each shape has six equal squares. Fold only along shared edges, without cutting or overlapping.",
        [multi("valid", "Welche Figuren sind gültige Würfelnetze? Wähle alle.", "Which shapes are valid cube nets? Select all.", [(x, x, x) for x in ["A", "B", "C", "D"]], ["A", "D"], s), manual("invalid", "Warum genügt die Anzahl von sechs Quadraten allein nicht?", "Why is having six squares alone insufficient?", "1 Punkt: Die Anordnung muss sechs verschiedene Würfelflächen ergeben; bei ungeeigneter Anordnung überdecken sich Flächen oder der Würfel bleibt offen. Ein konkretes richtiges Beispiel zu B oder C genügt.", "1 point: the arrangement must create six distinct cube faces; unsuitable layouts overlap or leave the cube open. A correct example using B or C is sufficient.", s)],
        "rehearsal", [("Prüfe neben der Anzahl auch, wohin die einzelnen Quadrate beim Falten gelangen.", "Check not only the count but where each square ends up when folded.")], ("A und D sind gültige Netze. B ist ein 2-mal-3-Rechteck; C eine Reihe aus sechs Quadraten. Diese Anordnungen bilden keinen Würfel ohne Überlappung.", "A and D are valid nets. B is a 2-by-3 rectangle and C a row of six squares. These layouts cannot form a cube without overlapping."),
        fig=figure("shapeComparison", {"shapes": net_shapes}, "Vier Sechserfiguren: A ein Kreuz mit verlängertem unteren Arm; B ein 2-mal-3-Rechteck; C eine Reihe aus sechs; D eine Viererreihe mit versetzten Quadraten oben und unten.", "Four six-square shapes: A a cross with extended lower arm; B a 2-by-3 rectangle; C a row of six; D a row of four with offset upper and lower squares."), level=3, seconds=145)

