        [number("perimeter_a", "Wie groß ist der Umfang von A?", "What is the perimeter of A?", 26, s, unit="cm"), number("perimeter_b", "Wie groß ist der Umfang von B?", "What is the perimeter of B?", 14, s, unit="cm"), choice("claim", "Beide haben 12 cm² Fläche. Müssen deshalb auch ihre Umfänge gleich sein?", "Both have area 12 cm². Must their perimeters therefore be equal?", [("yes", "Ja", "Yes"), ("no", "Nein", "No")], "no", s)],
